def widest_banner(posts):
    i, j = 0, len(posts) - 1
    best = 0
    while i < j:
        h = min(posts[i], posts[j])
        best = max(best, h * (j - i))
        if posts[i] < posts[j]:
            i += 1
        else:
            j -= 1
    return best

